css:
.dots::before{content:"・・・・・";letter-spacing:.4em;color:#c8bda6;font-size:11px;display:block;margin:18px 0}
.sep{border:0;border-top:2px dotted rgba(255,214,200,.55);margin:34px 0}
.body{border-top:1px dashed #c9c9c9;padding-top:20px;margin-top:26px}
/* ▼3連で次へ送る */
.arrow{display:grid;gap:6px;justify-items:center;margin:10px 0}
.arrow i{width:0;height:0;border:6px solid transparent;border-top:8px solid #12569e}
/* 四芒星8個、1個目だけ濃色 */
.sparkles{display:flex;gap:6px}
.sparkles i{width:9px;height:9px;background:#fff;clip-path:polygon(50% 0,60% 40%,100% 50%,60% 60%,50% 100%,40% 60%,0 50%,40% 40%)}
.sparkles i:first-child{background:#0d6f8c}
/* 実線を残すなら中央に菱形 */
.rule{position:relative;width:56%;height:1px;margin:14px auto;background:#c9b98a}
.rule::after{content:"";position:absolute;left:50%;top:-3px;translate:-50% 0;width:5px;height:7px;background:#c9b98a;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%)}
/* オーナメント行 */
.orn{border:0;height:12px;background:url(flower-dot.svg) repeat-x center/auto 12px;opacity:.55;margin:10px 0}
